1	package netproxy
2	
3	import (
4		"go/ast"
5		"go/parser"
6		"go/token"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"regexp"
11		"slices"
12		"strconv"
13		"strings"
14		"sync"
15		"testing"
16	)
17	
18	// DEVDESK-583: the guard that keeps every container launch of the scanners on
19	// containerRun.cmd (internal/scan/container_run.go), the one place that forwards
20	// the proxy variables into the container. Like the HTTP guard it parses the
21	// production sources of the whole module (go/ast, no type information) and
22	// reports the two ways code has found to build a `docker|podman run`:
23	//
24	//	C1  a []string literal whose first element is "run"
25	//	C2  a call with the literal "run" as argument 0 or 1 and at least one
26	//	    argument after it: exec.Command(bin, "run", img), dockerCombined("run", ...)
27	//
28	// A label such as cmdLabel("run") has no argument after "run" and is not
29	// reported. What the guard cannot see (a "run" assembled at run time, a
30	// "container run" spelling) is documented in docs/architecture/network.md.
31	
32	const (
33		ruleContainerSlice = "C1"
34		ruleContainerCall  = "C2"
35	
36		// containerRunFile and containerRunFunc are the one site allowed to build a
37		// run. It is hard-coded here and not an exception: it is the entry point.
38		containerRunFile = "internal/scan/container_run.go"
39		containerRunFunc = "containerRun.cmd"
40	)
41	
42	var containerRules = []string{ruleContainerSlice, ruleContainerCall}
43	
44	// containerExceptions is the whole list. Each entry is also named in the
45	// "Container scanners" section of docs/architecture/network.md
46	// (TestNetworkDocListsEveryContainerException).
47	var containerExceptions = []exception{
48		{
49			File: "internal/docker/launch.go", Func: "buildLaunchArgs", Rule: ruleContainerSlice,
50			Why:   "the user's own container, configured in the launch form; not a scanner (outside DEVDESK-583)",
51			Until: "permanent",
52		},
53		{
54			File: "internal/docker/launch.go", Func: "VerifyEntrypoint", Rule: ruleContainerCall,
55			Why:   "runs only `command -v`, nothing to forward",
56			Until: "permanent",
57		},
58	}
59	
60	// isRunLiteral reports whether e is the string literal "run" (or `run`).
61	func isRunLiteral(e ast.Expr) bool {
62		lit, ok := e.(*ast.BasicLit)
63		if !ok || lit.Kind != token.STRING {
64			return false
65		}
66		s, err := strconv.Unquote(lit.Value)
67		return err == nil && s == "run"
68	}
69	
70	// isStringSlice reports whether t is the type expression []string.
71	func isStringSlice(t ast.Expr) bool {
72		at, ok := t.(*ast.ArrayType)
73		if !ok || at.Len != nil {
74			return false
75		}
76		id, ok := at.Elt.(*ast.Ident)
77		return ok && id.Name == "string"
78	}
79	
80	// scanContainerSource parses src as the file name (a slash path from the module
81	// root) and returns its C1 and C2 violations ordered by line, then rule.
82	func scanContainerSource(name string, src []byte) ([]violation, error) {
83		fset := token.NewFileSet()
84		f, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
85		if err != nil {
86			return nil, err
87		}
88		var out []violation
89		add := func(pos token.Pos, rule, fn string) {
90			out = append(out, violation{File: name, Line: fset.Position(pos).Line, Rule: rule, Func: fn})
91		}
92		inspect := func(node ast.Node, fn string) {
93			ast.Inspect(node, func(n ast.Node) bool {
94				switch n := n.(type) {
95				case *ast.CompositeLit:
96					if n.Type != nil && isStringSlice(n.Type) && len(n.Elts) > 0 && isRunLiteral(n.Elts[0]) {
97						add(n.Pos(), ruleContainerSlice, fn)
98					}
99				case *ast.CallExpr:
100					for i := 0; i < 2 && i+1 < len(n.Args); i++ {
101						if isRunLiteral(n.Args[i]) {
102							add(n.Pos(), ruleContainerCall, fn)
103							break
104						}
105					}
106				}
107				return true
108			})
109		}
110		for _, decl := range f.Decls {
111			switch d := decl.(type) {
112			case *ast.FuncDecl:
113				inspect(d, funcName(d))
114			case *ast.GenDecl:
115				for _, spec := range d.Specs {
116					switch sp := spec.(type) {
117					case *ast.ValueSpec:
118						inspect(sp, sp.Names[0].Name)
119					case *ast.TypeSpec:
120						inspect(sp, sp.Name.Name)
121					}
122				}
123			}
124		}
125		slices.SortStableFunc(out, func(a, b violation) int {
126			if a.Line != b.Line {
127				return a.Line - b.Line
128			}
129			return strings.Compare(a.Rule, b.Rule)
130		})
131		return out, nil
132	}
133	
134	// scanContainerTree scans every non-test .go file under root, with the same
135	// exclusions as the HTTP guard (guardExcludedDirs, matched on the names below
136	// root) but internal/netproxy included: nothing there launches a container
137	// either. It also returns the number of files read.
138	func scanContainerTree(root string) ([]violation, int, error) {
139		var all []violation
140		files := 0
141		err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
142			if err != nil {
143				return err
144			}
145			rel, err := filepath.Rel(root, p)
146			if err != nil {
147				return err
148			}
149			rel = filepath.ToSlash(rel)
150			if d.IsDir() {
151				if rel != "." && slices.Contains(guardExcludedDirs, d.Name()) {
152					return filepath.SkipDir
153				}
154				return nil
155			}
156			if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
157				return nil
158			}
159			src, err := os.ReadFile(p)
160			if err != nil {
161				return err
162			}
163			vs, err := scanContainerSource(rel, src)
164			if err != nil {
165				return err
166			}
167			files++
168			all = append(all, vs...)
169			return nil
170		})
171		return all, files, err
172	}
173	
174	var (
175		containerOnce       sync.Once
176		containerViolations []violation
177		containerFiles      int
178		containerErr        error
179	)
180	
181	// scanContainerRepo scans the module that holds this package, once per test
182	// process, and returns its root.
183	func scanContainerRepo(t *testing.T) (string, []violation) {
184		t.Helper()
185		root, _ := scanRepo(t)
186		containerOnce.Do(func() {
187			containerViolations, containerFiles, containerErr = scanContainerTree(root)
188		})
189		if containerErr != nil {
190			t.Fatalf("scanning the module for container launches: %v", containerErr)
191		}
192		// A walk that reads almost nothing would pass for the wrong reason.
193		if containerFiles < 50 {
194			t.Fatalf("the container guard read %d files under %s, want the whole module", containerFiles, root)
195		}
196		return root, containerViolations
197	}
198	
199	// isContainerEntryPoint reports whether v is in the one function allowed to
200	// build a run.
201	func isContainerEntryPoint(v violation) bool {
202		return v.File == containerRunFile && v.Func == containerRunFunc
203	}
204	
205	// No scanner launches a container but through containerRun.cmd, which forwards
206	// the proxy variables; the listed exceptions are not scanners.
207	func TestContainerGuardNoLaunchBypassesTheProxyForward(t *testing.T) {
208		_, vs := scanContainerRepo(t)
209		for _, v := range vs {
210			if isContainerEntryPoint(v) {
211				continue
212			}
213			if slices.ContainsFunc(containerExceptions, func(e exception) bool { return e.covers(v) }) {
214				continue
215			}
216			t.Errorf("%s: builds a container run by hand; build it with containerRun in %s so the proxy variables are forwarded (containerRun.cmd), or add a reasoned exception to containerExceptions and to docs/architecture/network.md", v, containerRunFile)
217		}
218	}
219	
220	// An exception that matches nothing is stale, and so is an entry point that no
221	// longer builds the run: the guard would pass with nothing left to guard.
222	func TestContainerGuardEveryExceptionStillMatches(t *testing.T) {
223		_, vs := scanContainerRepo(t)
224		if !slices.ContainsFunc(vs, isContainerEntryPoint) {
225			t.Errorf("%s no longer builds a run in %s; the entry point moved, update containerRunFile/containerRunFunc and the doc", containerRunFunc, containerRunFile)
226		}
227		seen := map[exception]bool{}
228		for _, e := range containerExceptions {
229			key := exception{File: e.File, Func: e.Func, Rule: e.Rule}
230			if seen[key] {
231				t.Errorf("exception %s %s %s is listed twice", e.File, e.Func, e.Rule)
232			}
233			seen[key] = true
234			if !slices.Contains(containerRules, e.Rule) {
235				t.Errorf("exception %s %s: rule %q is not one of %v", e.File, e.Func, e.Rule, containerRules)
236			}
237			if strings.TrimSpace(e.Why) == "" || strings.TrimSpace(e.Until) == "" {
238				t.Errorf("exception %s %s %s needs a reason and an end (\"permanent\" or a story)", e.File, e.Func, e.Rule)
239			}
240			if !slices.ContainsFunc(vs, e.covers) {
241				t.Errorf("stale exception: %s %s %s matches no container launch any more; remove it from containerExceptions and docs/architecture/network.md", e.File, e.Func, e.Rule)
242			}
243		}
244	}
