246	func TestContainerGuardDetectors(t *testing.T) {
247		cases := []guardCase{
248			{
249				name: "a literal slice starting with run",
250				src: `package p
251	func a() []string { return []string{"run", "--rm"} }
252	`,
253				want: []string{"x.go:2: C1 (a)"},
254			},
255			{
256				name: "a one-element slice with run",
257				src: `package p
258	func a(x []string) []string { return append([]string{"run"}, x...) }
259	`,
260				want: []string{"x.go:2: C1 (a)"},
261			},
262			{
263				name: "a slice with run at package scope",
264				src: `package p
265	var base = []string{"run", "-d"}
266	`,
267				want: []string{"x.go:2: C1 (base)"},
268			},
269			{
270				name: "a slice with run in a closure belongs to its declaration",
271				src: `package p
272	type T struct{}
273	func (t *T) m() func() []string {
274		return func() []string { return []string{"run", "x"} }
275	}
276	`,
277				want: []string{"x.go:4: C1 (T.m)"},
278			},
279			{
280				name: "run at argument 1 of a call",
281				src: `package p
282	import "os/exec"
283	func a(b, i string) { _ = exec.Command(b, "run", i) }
284	`,
285				want: []string{"x.go:3: C2 (a)"},
286			},
287			{
288				name: "run at argument 0 of a call",
289				src: `package p
290	func f(a ...string) {}
291	func a() { f("run", "--rm") }
292	`,
293				want: []string{"x.go:3: C2 (a)"},
294			},
295			{
296				name: "run followed by a spread",
297				src: `package p
298	func f(a string, b ...string) {}
299	func a(x []string) { f("run", x...) }
300	`,
301				want: []string{"x.go:3: C2 (a)"},
302			},
303			{
304				name: "a label with run alone",
305				src: `package p
306	func cmdLabel(s string) string { return s }
307	func a() string { return cmdLabel("run") }
308	`,
309			},
310			{
311				name: "run last, with nothing after it",
312				src: `package p
313	func f(a, b string) {}
314	func a() { f("x", "run") }
315	`,
316			},
317			{
318				name: "run at argument 2 is not a launch",
319				src: `package p
320	func f(a, b, c, d string) {}
321	func a() { f("x", "y", "run", "z") }
322	`,
323			},
324			{
325				name: "run after another element in a slice",
326				src: `package p
327	func a() []string { return []string{"--rm", "run"} }
328	`,
329			},
330			{
331				name: "a slice of another type",
332				src: `package p
333	func a() []any { return []any{"run", "x"} }
334	`,
335			},
336			{
337				name: "a constant is not a launch",
338				src: `package p
339	const s = "run"
340	var t = "run"
341	`,
342			},
343			{
344				name: "a longer word is not run",
345				src: `package p
346	func f(a, b, c string) {}
347	func a() { f("x", "runner", "y"); _ = []string{"running"} }
348	`,
349			},
350		}
351		for _, tc := range cases {
352			t.Run(tc.name, func(t *testing.T) {
353				vs, err := scanContainerSource("x.go", []byte(tc.src))
354				if err != nil {
355					t.Fatalf("the synthetic source does not parse: %v", err)
356				}
357				got := make([]string, len(vs))
358				for i, v := range vs {
359					got[i] = v.String()
360				}
361				if !slices.Equal(got, tc.want) {
362					t.Errorf("report =\n  %s\nwant\n  %s", strings.Join(got, "\n  "), strings.Join(tc.want, "\n  "))
363				}
364			})
365		}
366	
367		// Every rule has at least one case that triggers it, so a rule cannot be
368		// dropped from the detector while the table stays green.
369		t.Run("every rule is exercised", func(t *testing.T) {
370			for _, r := range containerRules {
371				if !slices.ContainsFunc(cases, func(tc guardCase) bool {
372					return slices.ContainsFunc(tc.want, func(w string) bool { return strings.Contains(w, ": "+r+" (") })
373				}) {
374					t.Errorf("no detector case triggers %s", r)
375				}
376			}
377		})
378	}
