380	// The walk: the excluded directory names apply below the root only (a root under
381	// .worktrees is still scanned), test files are skipped, and, unlike the HTTP
382	// guard, internal/netproxy is read.
383	func TestContainerGuardWalk(t *testing.T) {
384		root := filepath.Join(t.TempDir(), ".worktrees", "feat", "wt")
385		bad := "package p\nfunc a() []string { return []string{\"run\"} }\n"
386		files := map[string]string{
387			"go.mod":                     "module example.com/m\n",
388			"main.go":                    bad,
389			"pkg/deep/ok.go":             bad,
390			"pkg/clean.go":               "package p\n",
391			"pkg/thing_test.go":          bad,
392			"internal/netproxy/own.go":   bad,
393			".worktrees/other/w.go":      bad,
394			"pkg/.worktrees/nested/w.go": bad,
395			".git/hooks/h.go":            bad,
396			"vendor/v/v.go":              bad,
397			"pkg/testdata/t.go":          bad,
398			"docs-site/node/d.go":        bad,
399			"web/node_modules/n/n.go":    bad,
400			"README.md":                  "not go",
401		}
402		for name, content := range files {
403			p := filepath.Join(root, filepath.FromSlash(name))
404			if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
405				t.Fatal(err)
406			}
407			if err := os.WriteFile(p, []byte(content), 0o600); err != nil {
408				t.Fatal(err)
409			}
410		}
411		vs, n, err := scanContainerTree(root)
412		if err != nil {
413			t.Fatal(err)
414		}
415		var got []string
416		for _, v := range vs {
417			got = append(got, v.String())
418		}
419		want := []string{
420			"internal/netproxy/own.go:2: C1 (a)",
421			"main.go:2: C1 (a)",
422			"pkg/deep/ok.go:2: C1 (a)",
423		}
424		slices.Sort(got)
425		if !slices.Equal(got, want) {
426			t.Errorf("scanContainerTree reported\n  %s\nwant\n  %s", strings.Join(got, "\n  "), strings.Join(want, "\n  "))
427		}
428		if n != 4 {
429			t.Errorf("scanContainerTree read %d files, want 4 (main.go, pkg/clean.go, pkg/deep/ok.go, internal/netproxy/own.go)", n)
430		}
431	}
