433	// containerDocSection is the part of the document under the heading that names
434	// the container scanners, up to the next heading of the same or a higher level.
435	func containerDocSection(md string) (string, bool) {
436		heading := regexp.MustCompile(`^(#+)\s`)
437		var out []string
438		level := 0
439		for _, line := range strings.Split(md, "\n") {
440			if m := heading.FindStringSubmatch(line); m != nil {
441				switch {
442				case level == 0 && strings.Contains(strings.ToLower(line), "container scanners"):
443					level = len(m[1])
444				case level != 0 && len(m[1]) <= level:
445					return strings.Join(out, "\n"), true
446				}
447			}
448			if level != 0 {
449				out = append(out, line)
450			}
451		}
452		return strings.Join(out, "\n"), level != 0
453	}
454	
455	func TestContainerGuardDocSection(t *testing.T) {
456		md := "# Network\n\n## Other\nnot this\n\n## Container scanners\nin `a.go`\n### Sub\nin sub\n## Next\nnot this\n"
457		got, ok := containerDocSection(md)
458		if !ok || !strings.Contains(got, "a.go") || !strings.Contains(got, "in sub") ||
459			strings.Contains(got, "not this") {
460			t.Errorf("containerDocSection = %q, %v", got, ok)
461		}
462		if _, ok := containerDocSection("# Network\n## Other\n"); ok {
463			t.Error("a document without the heading reported a section")
464		}
465	}
466	
467	// The exceptions the guard allows are the exceptions the doc lists.
468	func TestNetworkDocListsEveryContainerException(t *testing.T) {
469		root, _ := scanContainerRepo(t)
470		raw, err := os.ReadFile(filepath.Join(root, "docs", "architecture", "network.md"))
471		if err != nil {
472			t.Fatal(err)
473		}
474		section, ok := containerDocSection(string(raw))
475		if !ok {
476			t.Fatal("docs/architecture/network.md has no section whose heading names the container scanners")
477		}
478		for _, e := range containerExceptions {
479			if !strings.Contains(section, e.File) {
480				t.Errorf("the container scanners section does not name the file %s (exception %s %s)", e.File, e.Func, e.Rule)
481			}
482			if !strings.Contains(section, e.Func) {
483				t.Errorf("the container scanners section does not name %s (exception in %s, %s)", e.Func, e.File, e.Rule)
484			}
485		}
486	}
