80	// scanContainerSource parses src as the file name (a slash path from the module
81	// root) and returns its C1 and C2 violations ordered by line, then rule.
82	func scanContainerSource(name string, src []byte) ([]violation, error) {
83		fset := token.NewFileSet()
84		f, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
85		if err != nil {
86			return nil, err
87		}
88		var out []violation
89		add := func(pos token.Pos, rule, fn string) {
90			out = append(out, violation{File: name, Line: fset.Position(pos).Line, Rule: rule, Func: fn})
91		}
92		inspect := func(node ast.Node, fn string) {
93			ast.Inspect(node, func(n ast.Node) bool {
94				switch n := n.(type) {
95				case *ast.CompositeLit:
96					if n.Type != nil && isStringSlice(n.Type) && len(n.Elts) > 0 && isRunLiteral(n.Elts[0]) {
97						add(n.Pos(), ruleContainerSlice, fn)
98					}
99				case *ast.CallExpr:
100					for i := 0; i < 2 && i+1 < len(n.Args); i++ {
101						if isRunLiteral(n.Args[i]) {
102							add(n.Pos(), ruleContainerCall, fn)
103							break
104						}
105					}
106				}
107				return true
108			})
109		}
110		for _, decl := range f.Decls {
111			switch d := decl.(type) {
112			case *ast.FuncDecl:
113				inspect(d, funcName(d))
114			case *ast.GenDecl:
115				for _, spec := range d.Specs {
116					switch sp := spec.(type) {
117					case *ast.ValueSpec:
118						inspect(sp, sp.Names[0].Name)
119					case *ast.TypeSpec:
120						inspect(sp, sp.Name.Name)
121					}
122				}
123			}
124		}
125		slices.SortStableFunc(out, func(a, b violation) int {
126			if a.Line != b.Line {
127				return a.Line - b.Line
128			}
129			return strings.Compare(a.Rule, b.Rule)
130		})
131		return out, nil
132	}
