import _ "github.com/zalando/go-keyring"
func main() {}
`,
			want: []string{"2 K1"},
		},
		{
			name: "K1: a dot import",
			file: "internal/ui/setup/x_test.go",
			src: `package setup
import . "github.com/zalando/go-keyring"
`,
			want: []string{"2 K1"},
		},
		{
